<?php
require_once __DIR__.'/session.php';
require_once __DIR__.'/prediction_engine.php';
require_once __DIR__.'/layout.php';
$area=valid_area(request_value($_GET,'area',1));$until=request_value($_GET,'until',date('Y-m-d'));
$days=max(1,min(365,(int)request_value($_GET,'days',7)));$engine=request_value($_GET,'engine','pso')==='linear'?'linear':'pso';$error='';
try{if(!prediction_date($until))throw new Exception('Choose a valid date, no later than today.');$bundle=prediction_bundle($area,$until,$days,$engine);}catch(Exception $e){$error=$e->getMessage();}
page_start('Prediction and Drought Risk',$area);
?>
<link rel="stylesheet" href="css/prediction.css">
<div class="prediction-heading"><span class="eyebrow">FIELD INTELLIGENCE / AREA <?= $area ?></span><h2>Prediction &amp; Drought Outlook</h2><p>Explore sensor trends and identify potential moisture stress.</p></div>
<form class="filters prediction-filters" method="get"><input type="hidden" name="area" value="<?= $area ?>"><label>Use data until<input type="date" name="until" value="<?= h(is_string($until)?$until:date('Y-m-d')) ?>" max="<?= date('Y-m-d') ?>" required></label><label>Prediction days<input type="number" name="days" value="<?= $days ?>" min="1" max="365" required></label><label>Prediction method<select name="engine"><option value="pso" <?= $engine==='pso'?'selected':'' ?>>PSO-LightGBM</option><option value="linear" <?= $engine==='linear'?'selected':'' ?>>Linear trend baseline</option></select></label><button class="button">Generate outlook</button></form>
<?php if($error):?><p class="notice" role="alert"><?= h($error) ?></p><?php else:
$rows=$bundle['rows'];$peak=$rows[0];$counts=array('Low'=>0,'Medium'=>0,'High'=>0);foreach($rows as $r){$counts[$r['risk']['level']]++;if($r['risk']['score']>$peak['risk']['score'])$peak=$r;}$risk=$peak['risk'];
?>
<div class="model-strip"><strong>PSO-LightGBM</strong><span class="model-state"><?= $bundle['available']?'Model ready':'Awaiting training' ?></span><p>Active forecast: <strong><?= h($bundle['mode']) ?></strong> · <?= $bundle['history_count'] ?> recorded days in the 30-day view</p><small><?= h($bundle['reason']) ?></small></div>
<section class="outlook-grid" aria-label="Forecast graph and drought assessment"><article class="outlook-panel chart-panel"><div class="panel-title"><div><span class="eyebrow">SENSOR FORECAST</span><h3>Moisture &amp; risk trend</h3></div><span class="range-pill"><?= $days ?> days</span></div><div class="chart-legend"><span>Soil level %</span><span class="rain-key">Rain sensor %</span><span class="risk-key">Drought screening index</span></div>
<svg class="forecast-chart" viewBox="0 0 700 320" role="img" aria-labelledby="chart-title chart-desc"><title id="chart-title">Forecast using <?= h($bundle['mode']) ?></title><desc id="chart-desc">Soil and rain sensor percentages and rule-based drought index. Exact values are in the table below.</desc>
<?php for($tick=0;$tick<=100;$tick+=25):$y=260-$tick*2.1;?><line x1="48" y1="<?= $y ?>" x2="674" y2="<?= $y ?>" class="chart-grid"/><text x="36" y="<?= $y+4 ?>" text-anchor="end" class="chart-label"><?= $tick ?></text><?php endfor;
foreach(array('soil'=>'#149b77','rain'=>'#3485ed','risk'=>'#d27617') as $key=>$color){$points=array();foreach($rows as $i=>$r){$v=$key==='risk'?$r['risk']['score']:sensor_percent($r[$key]);$x=count($rows)===1?360:48+$i*626/(count($rows)-1);$points[]=round($x,2).','.round(260-$v*2.1,2);}?>
<polyline points="<?= implode(' ',$points) ?>" fill="none" stroke="<?= $color ?>" stroke-width="3" <?= $key==='risk'?'stroke-dasharray="7 5"':'' ?>/>
<?php if(count($rows)<=31)foreach($rows as $i=>$r){$v=$key==='risk'?$r['risk']['score']:sensor_percent($r[$key]);$x=count($rows)===1?360:48+$i*626/(count($rows)-1);?><circle cx="<?= $x ?>" cy="<?= 260-$v*2.1 ?>" r="4" fill="<?= $color ?>"><title><?= h($r['date'].' · '.$key.': '.round($v,1)) ?></title></circle><?php }}?>
<text x="48" y="294" class="chart-label"><?= h($rows[0]['date']) ?></text><text x="674" y="294" text-anchor="end" class="chart-label"><?= h($rows[count($rows)-1]['date']) ?></text></svg><p class="chart-note">Dashed line: screening index, not probability. <?= $bundle['mode']==='Constant baseline'?'A flat line repeats available values because history is insufficient.':'Uncertainty increases with forecast horizon.' ?></p></article>
<aside class="outlook-panel drought-panel risk-<?= h($risk['class']) ?>"><span class="eyebrow">DROUGHT RISK OUTLOOK</span><h3>Moisture stress screening</h3><div class="risk-orbit"><span><?= h($risk['level']) ?></span><strong><?= number_format($risk['score'],1) ?><small>/100</small></strong></div><p class="risk-date">Highest estimated risk · <?= h($peak['date']) ?></p><div class="risk-scale"><span class="<?= $risk['level']==='Low'?'active':'' ?>">Low</span><span class="<?= $risk['level']==='Medium'?'active':'' ?>">Medium</span><span class="<?= $risk['level']==='High'?'active':'' ?>">High</span></div><p class="risk-advice"><?= $risk['level']==='High'?'Inspect soil and crop condition promptly. Confirm calibration before deciding irrigation.':($risk['level']==='Medium'?'Watch for increasing moisture stress. Check root-zone conditions and review watering needs.':'Lower relative stress in these inputs. Continue monitoring; this does not rule out drought.') ?></p><div class="risk-counts"><?= $counts['Low'] ?> low · <?= $counts['Medium'] ?> medium · <?= $counts['High'] ?> high days</div></aside></section>
<details class="outlook-panel method-details"><summary>How this prediction is calculated</summary><p>PSO tunes LightGBM parameters against chronological validation data. A trained model forecasts sensor values; it is not a trained drought classifier. Without a compatible model, the active baseline is explicitly named above.</p><p>Drought index = 55% soil deficit + 20% rain-sensor deficit + 15% humidity deficit + 10% temperature stress. Deficit = 100 minus sensor percentage. Temperature stress = clamp((temperature − 20) × 5, 0, 100). Low: below 33; Medium: 33 to below 66; High: 66 and above.</p><p>These illustrative weights require field calibration. Higher soil/rain values mean wetter, matching the existing controller. Rain-sensor percentage is not rainfall volume. This is an experimental sensor-based indicator, not a validated drought forecast or irrigation command. Four areas represent a shared sensor feed.</p></details>
<div class="forecast-table-wrap"><table><caption>Daily outlook · <?= h($bundle['mode']) ?></caption><thead><tr><th>Date</th><th>Temp °C</th><th>Humidity %</th><th>Soil %</th><th>Rain %</th><th>Drought risk</th><th>Irrigation suggestion</th></tr></thead><tbody><?php foreach($rows as $r):$soil=sensor_percent($r['soil']);$rain=sensor_percent($r['rain']);?><tr><td><?= h($r['date']) ?></td><td><?= number_format($r['temp'],1) ?></td><td><?= number_format($r['hum'],1) ?></td><td><?= $soil ?></td><td><?= $rain ?></td><td><span class="risk-badge <?= h($r['risk']['class']) ?>"><?= h($r['risk']['level']) ?> · <?= $r['risk']['score'] ?></span></td><td><?= $rain>RAIN_WET_PERCENT?'Wait — rain detected':($soil<SOIL_DRY_PERCENT?'Soil is dry — irrigate':'Moisture level normal') ?></td></tr><?php endforeach;?></tbody></table></div>
<?php endif;page_end(); ?>
